import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/RateUser.css";


const RateUser = () => {
  const [usersToRate, setUsersToRate] = useState([]);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchUsers = async () => {
      const userId = sessionStorage.getItem("userId");
      if (!userId) return;

      try {
        const res = await fetch(`${API_BASE_URL}/api/ratings/partners/${userId}`);
        const data = await res.json();

        if (!Array.isArray(data)) {
          setError("Invalid data format received");
          return;
        }

        setUsersToRate(data);
      } catch (err) {
        console.error("Failed to load users to rate:", err);
        setError("Failed to load users.");
      }
    };

    fetchUsers();
  }, []);

  const handleRate = async (ratedUserId, rating) => {
    const raterId = sessionStorage.getItem("userId");
    try {
      const res = await fetch(`${API_BASE_URL}/api/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ rater_id: raterId, rated_id: ratedUserId, rating }),
      });

      if (res.ok) {
        alert("Rating submitted!");
        setUsersToRate(prev => prev.filter(user => user.id !== ratedUserId));
      } else {
        alert("Failed to submit rating.");
      }
    } catch (err) {
      console.error("Error rating user:", err);
      alert("Error rating user.");
    }
  };

  return (
    <div>
      <Navbar />
      <main className="rate-user-wrapper">
        <h2>Rate Other Users</h2>
        {error && <p style={{ color: "red" }}>{error}</p>}
        {!error && usersToRate.length === 0 ? (
          <p>No users to rate yet.</p>
        ) : (
          usersToRate.map((user) => (
            <div key={user.id} className="rate-card">
              <h4>{user.username}</h4>
              <p>{user.email}</p>
              <p><strong>Average Rating:</strong> {user.average_rating ?? "Not rated yet"}</p>
              <div className="rating-buttons">
                {[1, 2, 3, 4, 5].map((n) => (
                  <button key={n} onClick={() => handleRate(user.id, n)}>
                    {n} ⭐
                  </button>
                ))}
              </div>
            </div>
          ))
        )}
      </main>
      <Footer />
    </div>
  );
};

export default RateUser;
